update project_cost_questions set why_it_matters = '現行モデルの収入は処理費（オンサイト500円/m³、オフサイト50,000円/m³）のみ。レアアース回収のアップサイドが数字として表現できていない。', updated_at = now() where cost_question_id = 'cq_260820_10' and cost_model_id = 'cm_p21_260820';
update project_cost_questions set why_it_matters = 'オンサイトの売価500円/m³は「既存処理コスト500円/m³前後」という前提から置いた仮置き値で、用途別の実勢では未検証。ツムラヒアリングでは2,000〜3,000 m³/日の大規模工場で給水側OPEXが m³あたり1,000円行かないくらいだった。規模が小さいほど単価は上がるが、500円が妥当かどうかの一次情報がまだない。売価が動くと成立ラインが丸ごと動く。', updated_at = now() where cost_question_id = 'cq_260820_12' and cost_model_id = 'cm_p21_260820';
update project_cost_questions set question = '年間処理量がオンサイト20,000,000m³（売上10,000,000,000円）とオフサイト30,000m³のとき、菌体の製造拠点を何箇所に分けるかを決める。いまは培養設備の系列（色素分解で約67、金属回収で自然株 約795・強化株 約630）をすべて1拠点に並べる前提で計算している。', updated_at = now() where cost_question_id = 'cq_260820_16' and cost_model_id = 'cm_p21_260820';
update project_cost_questions set question = 'オフサイトで顧客の排液を受け入れて処理する場合に、産業廃棄物の収集運搬業・処分業の許可が要るか、要るなら取得にかかる期間と費用を確認する。特別管理産業廃棄物（pH2.0以下の廃酸、pH12.5以上の廃アルカリ、有害な金属などを基準より多く含む液）を受けるなら、特管の許可が別に要るので、その期間と費用、菌体での処理が処分の方法として認められるかも確認する。', why_it_matters = 'オフサイトが成り立つかは、運ぶ費用だけでなく許可でも決まる。費用と期間はモデルに入れていない。特管の液は割高でも引き取りを頼みたい需要があるかもしれない（2026-09-14 まさ）。特管の廃酸は全国で年約574千t、廃アルカリ約467千t、有害物質を含む廃アルカリ約367千t（令和元年度、環境省）で、染色施設・電気めっき施設・酸やアルカリによる表面処理施設は環境省の排出源の一覧に入っている。一方で許可と処分の基準は普通の産廃より厳しく、処理したあとも基準を超えるものは特管のまま扱う（廃棄物処理法施行令）。', updated_at = now() where cost_question_id = 'cq4_02' and cost_model_id = 'cm_p21_260820';
insert into project_cost_questions (cost_question_id, cost_model_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cq11_01', 'cm_p21_260820', '顧客候補（ヒアリング）', 'いま産業廃棄物として業者に出している液を教えてください。①液の種類（色・金属・酸やアルカリの強さ）②月あたりの量 ③色や金属の濃さ ④1Lあたりの処分費と、運ぶ費用が別ならその額。', 'オフサイトの売価（仮置き50,000円/m³＝1Lあたり50円）と年間処理量（30,000m³/年）の根拠になる。オフサイトは、ふつうの排水ではなく、自社で処理しにくい液に払っている額で成り立つ（2026-09-14 まさ「ペインがあれば割高でも成立するから」）。', null, null, 'open', null, null, 'ca11_offsite_sale_price', 'amd_internal', 350);
insert into project_cost_questions (cost_question_id, cost_model_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cq11_02', 'cm_p21_260820', '杉浦先生', '濃い液（色素や金属が数百〜数千mg/L）を、菌体で処理できますか。1回に処理できる濃さの上限と、濃いときに菌体を増やせば取り込みの割合（菌体1gあたり約0.05g）が保てるかを教えてください。まだ分からなければ、分からないと答えてください。', '産業廃棄物として引き取る液は、いまの試算の濃さ（50mg/L・50ppm）より濃いものが多い見込み（推測）。菌体の量は濃さに比例するので、金属回収・自然株で5,000ppmなら乾燥菌体が1m³あたり約130kg要る計算になる。処理できる濃さが、オフサイトで引き取れる液と売価を決める。', null, null, 'open', null, null, null, 'amd_internal', 360);

commit;
